using System;using System.Collections.Generic;using HarmonyLib;using RimWorld;using RimWorld.Planet;using UnityEngine;using Verse;using Verse.AI;
namespace ElementalHearts {
 public static class CelestialLightTravel {
  public const int DepartTicks=72,ArriveTicks=54;
  public static string Problem(Pawn p){if(p==null||!CelestialAscendant.Active(p)||!ElementalTeaching.Ready(p)||!ElementalCombatPolicy.Controlled(p))return "Requires a conscious player-controlled Celestial on a map.";if(CelestialAscendant.Busy(p)||ElementalAnimationBridge.Controlled(p)||ElementalTeachingSession.Busy(p)||HediffComp_ElementalTransform.Transforming(p)||AzureEvolution.Evolving(p))return "Finish the current action before traveling.";if(p.carryTracker!=null&&p.carryTracker.CarriedThing!=null)return "Put down the carried pawn or item before traveling.";return null;}
  public static bool DestinationAllowed(PlanetTile origin,PlanetTile destination){if(!origin.Valid||!destination.Valid||origin.Layer!=destination.Layer||origin==destination)return false;var tile=Find.WorldGrid[destination];return tile.PrimaryBiome!=BiomeDefOf.Ocean&&tile.PrimaryBiome.canBuildBase&&tile.hilliness!=Hilliness.Impassable;}
  public static Command_Action Command(Pawn p){var c=new Command_Action{defaultLabel="Light Travel",defaultDesc="Become sunlight and travel to any usable land tile on this world, then choose a safe arrival cell. No fuel, psyfocus, distance cost or cooldown. A short departure and huge arrival light beam frame the near-instant transfer. Gear, inventory and transformation state travel with you. Canceling the destination does nothing; canceled or unavailable landings retain you safely in transit with Land and Return controls. Solo travel; put down carried pawns/items first.",icon=CelestialVisualAssets.Icon(6),groupable=false,action=()=>Begin(p)};string problem=Problem(p);if(problem!=null)c.Disable(problem);return c;}
  public static void Begin(Pawn p){if(Problem(p)!=null)return;PlanetTile origin=p.Map.Tile;CameraJumper.TryJump(new GlobalTargetInfo(origin));Find.WorldTargeter.BeginTargeting(t=>{if(Problem(p)!=null||p.Map.Tile!=origin||!t.IsValid||!DestinationAllowed(origin,t.Tile))return false;return TryDepart(p,t.Tile);},true,CelestialVisualAssets.Icon(6),true,null,t=>t.IsValid&&DestinationAllowed(origin,t.Tile)?new TaggedString("Light Travel: no cost. Choose destination."):new TaggedString("Choose another usable land tile on this world."),t=>t.IsValid&&DestinationAllowed(origin,t.Tile),origin);}
  public static bool TryDepart(Pawn p,PlanetTile destination){if(Problem(p)!=null||!DestinationAllowed(p.Map.Tile,destination))return false;var c=HediffComp_CelestialAbilities.On(p);c.travelDestination=destination;var job=JobMaker.MakeJob(DefDatabase<JobDef>.GetNamed(CelestialAscendant.Depart),p.Position);job.playerForced=true;p.jobs.StartJob(job,JobCondition.InterruptForced,cancelBusyStances:true);if(p.CurJob==job)return true;c.travelDestination=PlanetTile.Invalid;return false;}
  public static bool Launch(Pawn p,PlanetTile destination){
   if(p==null||!p.Spawned||!CelestialAscendant.Active(p)||!ElementalTeaching.Ready(p)||!DestinationAllowed(p.Map.Tile,destination))return false;Map map=p.Map;IntVec3 at=p.Position;var flight=(WorldObject_CelestialLightTravel)WorldObjectMaker.MakeWorldObject(DefDatabase<WorldObjectDef>.GetNamed("EH_CelestialLightTravel"));flight.Tile=map.Tile;flight.destination=destination;flight.SetFaction(p.Faction);p.jobs.StopAll();p.DeSpawn();
   if(!flight.Container.TryAdd(p)){GenSpawn.Spawn(p,at,map);return false;}
   try{Find.WorldObjects.Add(flight);}catch(Exception e){flight.Container.Remove(p);GenSpawn.Spawn(p,at,map);Log.Error("[Elemental Hearts] Light Travel rolled back: "+e);return false;}
   Find.WorldSelector.ClearSelection();Find.WorldSelector.Select(flight);return true;
  }
  public static bool Safe(IntVec3 cell,Map map){if(map==null||!cell.InBounds(map)||!cell.Standable(map)||cell.Fogged(map)||cell.GetTerrain(map).passability==Traversability.Impassable)return false;foreach(var thing in cell.GetThingList(map))if(thing is Pawn||thing is Fire)return false;return true;}
 }
 public sealed class JobDriver_CelestialDepart:JobDriver {
  public int elapsed;bool launched;PlanetTile destination=PlanetTile.Invalid;int beam,seal;
  public override bool TryMakePreToilReservations(bool errorOnFailed){return true;}
  public override void ExposeData(){base.ExposeData();Scribe_Values.Look(ref elapsed,"EH_lightDepartElapsed");Scribe_Values.Look(ref launched,"EH_lightDepartLaunched");Scribe_Values.Look(ref destination,"EH_lightDepartDestination",PlanetTile.Invalid);}
  bool Valid(){return !launched&&pawn.CurJob==job&&CelestialAscendant.Active(pawn)&&ElementalTeaching.Ready(pawn)&&pawn.Position==job.targetA.Cell&&!ElementalAnimationBridge.ExternallyControlled(pawn);}
  void Cleanup(){if(pawn.Spawned){var vfx=pawn.Map.GetComponent<MapComponent_CelestialVfx>();vfx.Stop(beam);vfx.Stop(seal);}var c=HediffComp_CelestialAbilities.On(pawn);if(c!=null)c.travelDestination=PlanetTile.Invalid;}
  protected override IEnumerable<Toil> MakeNewToils(){AddFinishAction(condition=>Cleanup());this.FailOn(()=>!Valid());var departure=new Toil();departure.defaultCompleteMode=ToilCompleteMode.Never;departure.handlingFacing=true;departure.initAction=()=>{pawn.pather.StopDead();pawn.stances.CancelBusyStanceHard();if(!destination.Valid){var c=HediffComp_CelestialAbilities.On(pawn);if(c!=null)destination=c.travelDestination;}if(!destination.Valid){EndJobWith(JobCondition.Incompletable);return;}beam=CelestialVfx.Emit(pawn,CelestialEffect.DepartureBeam,pawn.DrawPos,pawn.DrawPos,CelestialLightTravel.DepartTicks,2.8f,8,null,elapsed);seal=CelestialVfx.Emit(pawn,CelestialEffect.SolarSeal,pawn.DrawPos,pawn.DrawPos,CelestialLightTravel.DepartTicks,3,3,null,elapsed);if(elapsed==0)ElementalAudio.Ability(pawn,ElementalSound.Charge);};departure.tickAction=()=>{pawn.pather.StopDead();if(++elapsed<CelestialLightTravel.DepartTicks)return;launched=true;var next=destination;CelestialVfx.Emit(pawn,CelestialEffect.TravelMotes,pawn.DrawPos,pawn.DrawPos,36,2.5f,2.5f);ElementalAudio.Play(pawn,"EH_TransformLock");if(!CelestialLightTravel.Launch(pawn,next)){launched=false;if(pawn.CurJob==job)EndJobWith(JobCondition.Incompletable);}};yield return departure;}
 }
 public sealed class JobDriver_CelestialArrive:JobDriver {
  public int elapsed;int beam,ring,motes;
  public override bool TryMakePreToilReservations(bool errorOnFailed){return true;}
  public override void ExposeData(){base.ExposeData();Scribe_Values.Look(ref elapsed,"EH_lightArriveElapsed");}
  void Cleanup(){if(!pawn.Spawned)return;var vfx=pawn.Map.GetComponent<MapComponent_CelestialVfx>();vfx.Stop(beam);vfx.Stop(ring);vfx.Stop(motes);}
  protected override IEnumerable<Toil> MakeNewToils(){AddFinishAction(condition=>Cleanup());this.FailOn(()=>!CelestialAscendant.Active(pawn)||!ElementalTeaching.Ready(pawn)||pawn.Position!=job.targetA.Cell||ElementalAnimationBridge.ExternallyControlled(pawn));var arrival=new Toil();arrival.defaultCompleteMode=ToilCompleteMode.Never;arrival.handlingFacing=true;arrival.initAction=()=>{pawn.pather.StopDead();pawn.stances.CancelBusyStanceHard();beam=CelestialVfx.Emit(pawn,CelestialEffect.ArrivalBeam,pawn.DrawPos,pawn.DrawPos,CelestialLightTravel.ArriveTicks,3.5f,10,null,elapsed);ring=CelestialVfx.Emit(pawn,CelestialEffect.ArrivalRing,pawn.DrawPos,pawn.DrawPos,CelestialLightTravel.ArriveTicks,5,5,null,elapsed);motes=CelestialVfx.Emit(pawn,CelestialEffect.TravelMotes,pawn.DrawPos,pawn.DrawPos,CelestialLightTravel.ArriveTicks,3,3,null,elapsed);pawn.Map.GetComponent<MapComponent_CelestialVfx>().Track(pawn);if(elapsed==0)ElementalAudio.Ability(pawn,ElementalSound.Impact);};arrival.tickAction=()=>{pawn.pather.StopDead();if(++elapsed>=CelestialLightTravel.ArriveTicks)ReadyForNextToil();};yield return arrival;}
 }
 public sealed class CelestialLandingSite:MapParent {
  public override bool ShouldRemoveMapNow(out bool alsoRemoveWorldObject){alsoRemoveWorldObject=true;if(!HasMap||Map.mapPawns.AnyPawnBlockingMapRemoval)return false;foreach(var world in Find.WorldObjects.AllWorldObjects){var travel=world as WorldObject_CelestialLightTravel;if(travel!=null&&travel.Container.Count>0&&(travel.destination==Tile||travel.Tile==Tile))return false;}return true;}
 }
 public sealed class WorldObject_CelestialLightTravel:WorldObject,IThingHolder {
  ThingOwner inner;public PlanetTile destination;public int remaining=1;bool arrivalQueued,awaitingLanding;
  public ThingOwner Container{get{return inner;}}
  public WorldObject_CelestialLightTravel(){inner=new ThingOwner<Thing>(this,false,LookMode.Deep);}
  public override Vector3 DrawPos{get{return Find.WorldGrid.GetTileCenter(destination.Valid?destination:Tile);}}
  public override void ExposeData(){base.ExposeData();Scribe_Deep.Look(ref inner,"EH_lightPassenger",this);Scribe_Values.Look(ref destination,"EH_lightDestination");Scribe_Values.Look(ref remaining,"EH_lightRemaining",1);Scribe_Values.Look(ref awaitingLanding,"EH_lightAwaitingLanding");if(Scribe.mode==LoadSaveMode.PostLoadInit){if(inner==null)inner=new ThingOwner<Thing>(this,false,LookMode.Deep);arrivalQueued=false;remaining=Math.Max(0,Math.Min(1,remaining));}}
  protected override void Tick(){base.Tick();if(remaining>0)remaining--;if(remaining==0&&!arrivalQueued&&!awaitingLanding)QueueArrival();}
  public override string GetInspectString(){return "Light Travel — no cost\n"+(remaining>0?"Crossing the world as sunlight.":"Awaiting arrival selection. Use Land to choose again, or Return to origin.");}
  public override IEnumerable<Gizmo> GetGizmos(){foreach(var g in base.GetGizmos())yield return g;yield return new Command_Action{defaultLabel="Land",defaultDesc="Choose a safe arrival cell. The original pawn remains held safely until placement succeeds.",icon=CelestialVisualAssets.Icon(6),action=()=>{if(!arrivalQueued)QueueArrival();}};yield return new Command_Action{defaultLabel="Return to origin",defaultDesc="Return to the departure tile for free, then choose a safe landing cell.",icon=CelestialVisualAssets.Icon(6),action=ReturnToOrigin};}
  public void ReturnToOrigin(){if(arrivalQueued)return;destination=Tile;remaining=1;awaitingLanding=false;}
  public Map PrepareDestination(){MapParent parent=Find.WorldObjects.MapParentAt(destination);if(parent==null){parent=(MapParent)WorldObjectMaker.MakeWorldObject(DefDatabase<WorldObjectDef>.GetNamed("EH_CelestialLandingSite"));parent.Tile=destination;parent.SetFaction(Faction.OfPlayer);Find.WorldObjects.Add(parent);}bool generated=!parent.HasMap;Map map=parent.HasMap?parent.Map:GetOrGenerateMapUtility.GetOrGenerateMap(destination,Find.World.info.initialMapSize,parent.def);if(generated&&map!=null){var spot=DropCellFinder.GetBestShuttleLandingSpot(map,Faction.OfPlayer);if(spot.IsValid)FloodFillerFog.FloodUnfog(spot,map);}return map;}
  void QueueArrival(){arrivalQueued=true;awaitingLanding=true;LongEventHandler.QueueLongEvent(()=>{try{Map map=PrepareDestination();LongEventHandler.ExecuteWhenFinished(()=>{arrivalQueued=false;if(map!=null)SelectLanding(map);});}catch(Exception e){arrivalQueued=false;Log.Error("[Elemental Hearts] Light Travel arrival retained passenger safely: "+e);Messages.Message("Arrival unavailable. The Celestial is safe in transit; use Land to retry or Return to origin.",MessageTypeDefOf.RejectInput,false);}},"GeneratingMap",true,null);}
  void SelectLanding(Map map){Find.TickManager.Pause();Current.Game.CurrentMap=map;CameraJumper.TryJump(map.Center,map);var target=TargetingParameters.ForCell();target.validator=t=>CelestialLightTravel.Safe(t.Cell,map);Find.Targeter.BeginTargeting(target,t=>TryLand(t.Cell,map),(Action<LocalTargetInfo>)null,null);Messages.Message("Light Travel: choose an unoccupied arrival cell. Canceling keeps your Celestial safe in transit; select its world icon and press Land to retry.",MessageTypeDefOf.NeutralEvent,false);}
  public bool TryLand(IntVec3 cell,Map map){if(map==null||map.Tile!=destination||inner.Count!=1||!CelestialLightTravel.Safe(cell,map))return false;Thing placed;Thing passenger=inner[0];if(!inner.TryDrop(passenger,cell,map,ThingPlaceMode.Direct,out placed))return false;var pawn=placed as Pawn;if(pawn!=null){pawn.Notify_Teleported();pawn.jobs.StartJob(JobMaker.MakeJob(DefDatabase<JobDef>.GetNamed(CelestialAscendant.Arrive),cell),JobCondition.InterruptForced,cancelBusyStances:true);Find.Selector.ClearSelection();Find.Selector.Select(pawn);}if(inner.Count==0)Find.WorldObjects.Remove(this);return true;}
  public ThingOwner GetDirectlyHeldThings(){return inner;}
  public void GetChildHolders(List<IThingHolder> children){ThingOwnerUtility.AppendThingHoldersFromThings(children,inner);}
 }
 [HarmonyPatch(typeof(GameEnder),"CheckOrUpdateGameOver")]
 public static class CelestialTransitColonyProtection {public static bool Prefix(ref bool ___gameEnding){if(Find.WorldObjects==null)return true;foreach(var world in Find.WorldObjects.AllWorldObjects){var flight=world as WorldObject_CelestialLightTravel;if(flight==null)continue;foreach(var thing in flight.Container){var pawn=thing as Pawn;if(pawn!=null&&!pawn.Dead&&pawn.IsFreeColonist){___gameEnding=false;return false;}}}return true;}}
}
